 func resolveWorkItems(ctx context.Context, tx *sql.Tx, siteID uuid.UUID,
 	checkName string, batchID uuid.UUID, r checks.ResolvedFinding, logger *zap.Logger) (int, error) {
 	switch { /* existing refusals unchanged */ }
+	if r.Receipt != nil {
+		rc := workItemFromSpec(*r.Receipt)
+		if rc.itemKey == "" {
+			return 0, fmt.Errorf("resolve %s/%s: receipt has no item_key — it could never be found again; retraction WITHHELD", r.ItemType, r.ItemKey)
+		}
+		inserted, rErr := insertWorkItem(ctx, tx, rc, logger)
+		if rErr != nil {
+			return 0, fmt.Errorf("resolve %s/%s: receipt %q could not be written — retraction WITHHELD: %w", r.ItemType, r.ItemKey, rc.itemKey, rErr)
+		}
+		if !inserted {
+			var present int
+			if qErr := tx.QueryRowContext(ctx, fmt.Sprintf(`SELECT 1 FROM site_work_items
+				 WHERE site_id = $1 AND item_key = $2 AND status NOT IN (%s) LIMIT 1`,
+				sqlInList(workItemClosedStatuses)), siteID, rc.itemKey).Scan(&present); qErr != nil {
+				return 0, fmt.Errorf("resolve %s/%s: receipt %q was neither inserted nor found open (%v) — retraction WITHHELD", r.ItemType, r.ItemKey, rc.itemKey, qErr)
+			}
+		}
+	}
+	evidenceSQL, args := "", []interface{}{checkName, r.Reason, siteID, r.ItemType, r.ItemKey, batchID}
+	if len(r.Evidence) > 0 {
+		blob, mErr := json.Marshal(r.Evidence)
+		if mErr != nil {
+			return 0, fmt.Errorf("resolve %s/%s: evidence is not marshalable — retraction WITHHELD: %w", r.ItemType, r.ItemKey, mErr)
+		}
+		evidenceSQL = " || $7::jsonb"
+		args = append(args, string(blob))
+	}
 	res, err := tx.ExecContext(ctx, fmt.Sprintf(`
 		UPDATE site_work_items
 		   SET status = 'complete', completed_at = now(), updated_at = now(),
 		       result = COALESCE(result, '{}'::jsonb) || jsonb_build_object(
-		                    'resolved_by', $1::text, 'reason', $2::text, 'resolved_at', now()::text)
+		                    'resolved_by', $1::text, 'reason', $2::text, 'resolved_at', now()::text)%s
 		 WHERE site_id = $3 AND item_type = $4 AND ($5::text = '' OR item_key = $5::text)
 		   AND status NOT IN (%s) AND batch_id IS DISTINCT FROM $6::uuid`,
-		sqlInList(workItemClosedStatuses)), checkName, r.Reason, siteID, r.ItemType, r.ItemKey, batchID)
+		evidenceSQL, sqlInList(workItemClosedStatuses)), args...)

+func sectionMultisetDiff(have, want []string) []string {
+	budget := make(map[string]int, len(want))
+	for _, s := range want { budget[s]++ }
+	out := []string{}
+	for _, s := range have {
+		if budget[s] > 0 { budget[s]--; continue }
+		out = append(out, s)
+	}
+	return out
+}
+
+func classifyDriftResolution(it driftItemSnapshot, pageID *uuid.UUID,
+	rawCacheToday, mergedToday []string, serving string) driftResolution {
+	r := driftResolution{item: it, pageID: pageID, agreed: mergedToday, serving: serving}
+	switch {
+	case orderedListsEqual(rawCacheToday, it.PagesSections): r.direction = "cache_held"
+	case orderedListsEqual(rawCacheToday, it.Authoritative): r.direction = "authority_won"
+	default:                                                 r.direction = "third_list"
+	}
+	cacheOnly := sectionMultisetDiff(it.PagesSections, it.Authoritative)
+	r.lost   = sectionMultisetDiff(cacheOnly, mergedToday)
+	r.gained = sectionMultisetDiff(mergedToday, it.PagesSections)
+	r.reordered = len(r.lost) == 0 && len(r.gained) == 0 && !orderedListsEqual(mergedToday, it.PagesSections)
+	return r
+}
+
+func (r driftResolution) retraction(dctx DiscoveryCheckContext, historyRows map[string]int) ResolvedFinding {
+	f := ResolvedFinding{ItemType: "section_source_drift", ItemKey: r.item.ItemKey,
+		Reason: fmt.Sprintf("re-read: %s and pages.sections agree again on page %q (direction=%s, lost=[%s], gained=[%s])",
+			r.serving, r.item.PageName, r.direction, strings.Join(r.lost, ", "), strings.Join(r.gained, ", ")),
+		Evidence: r.evidence()}
+	if len(r.lost) == 0 { return f }
+	rc := r.receipt(dctx, historyRows)
+	f.Receipt = &rc
+	f.Evidence["receipt_item_key"] = rc.ItemKey
+	return f
+}
+
+func (c *SectionSourceDriftCheck) appendRetractions(dctx DiscoveryCheckContext, result *CheckResult,
+	tableSections, aspectSections, cacheSections map[string][]string,
+	cachePageIDs map[string]uuid.UUID, lockedByPage map[string][]datahelpers.LockedPageSlot) error {
+	items, err := loadOpenDriftItems(dctx)
+	if err != nil { return err }
+	authorityReadProductive := len(tableSections) > 0 || len(aspectSections) > 0
+	for _, it := range items {
+		cache, present := cacheSections[it.PageName]
+		if !present { continue }   // absence is not an observation
+		authoritative, serving, hasAuthority := effectiveAuthoritative(it.PageName, tableSections, aspectSections)
+		if !hasAuthority {
+			if !authorityReadProductive { continue }   // DEMAND CONTROL
+			authoritative, serving = cache, "pages.sections"
+		}
+		mergedAuth, mergedCache := mergeBothSides(authoritative, cache, lockedByPage[it.PageName])
+		if !orderedListsEqual(mergedAuth, mergedCache) { continue }
+		res := classifyDriftResolution(it, pageIDOf(cachePageIDs, it.PageName), cache, mergedCache, serving)
+		result.Resolved = append(result.Resolved, res.retraction(dctx, countArchivedSlotRows(dctx, res)))
+	}
+	return nil
+}

 	// in Run, BEFORE the filing loop and before the per-pass cap:
+	if err := c.appendRetractions(dctx, result, tableSections, aspectSections,
+		cacheSections, cachePageIDs, lockedByPage); err != nil {
+		dctx.Logger.Warn("section_source_drift: retraction pass degraded — filing continues", zap.Error(err))
+	}

 	// in the filing loop:
+		wouldDrop := sectionMultisetDiff(mergedCache, mergedAuth)
+		wouldDropPresent := namesPresentOnPage(wouldDrop, liveSlots[pageName])
+		severity := "medium"
+		if len(wouldDropPresent) > 0 { severity = "high" }
+		if len(wouldDropPresent) > 0 {
+			summary = fmt.Sprintf("Next build will DROP [%s] from page '%s' (on the page now); %s",
+				strings.Join(wouldDropPresent, ", "), pageName, summary)
+		}

