+func TestLockedRowIsNeverReportedLost(t *testing.T) {
+	res := classifyDriftResolution(driftItemSnapshot{PageName: "contact",
+		Authoritative: []string{"hero","contact-form"},
+		PagesSections: []string{"hero","contact-form","chat-input-box"}},
+		nil, []string{"hero","contact-form"},
+		[]string{"hero","contact-form","chat-input-box"}, "site_plan_sections")
+	if len(res.lost) != 0 {
+		t.Fatalf("lost = %v — a locked row STILL ON THE PAGE was reported destroyed", res.lost)
+	}
+}
